CREATE EXTENSION IF NOT EXISTS pg_trgm;
CREATE TABLE sources (id varchar(100) PRIMARY KEY, name varchar(200) NOT NULL, terms_url text, license text, enabled boolean NOT NULL DEFAULT false);
CREATE TABLE companies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, isin varchar(12), ticker varchar(32), lei varchar(20), cin varchar(32));
CREATE INDEX companies_name_trgm_idx ON companies USING gin (name gin_trgm_ops);
CREATE INDEX companies_ticker_idx ON companies(ticker);
CREATE TABLE source_facts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_id varchar(100) REFERENCES sources(id), entity_name text NOT NULL, fact_type varchar(100) NOT NULL, payload jsonb NOT NULL, source_url text, retrieved_at timestamptz NOT NULL, confidence varchar(40) NOT NULL, sample boolean NOT NULL DEFAULT false);
CREATE TABLE ingestion_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_id varchar(100) REFERENCES sources(id), started_at timestamptz NOT NULL, completed_at timestamptz, status varchar(30) NOT NULL, error_summary text);
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email varchar(320) UNIQUE NOT NULL, password_hash text NOT NULL, approved boolean NOT NULL DEFAULT false, enabled boolean NOT NULL DEFAULT true);
CREATE TABLE roles (id bigserial PRIMARY KEY, name varchar(32) UNIQUE NOT NULL);
CREATE TABLE user_roles (user_id uuid REFERENCES users(id), role_id bigint REFERENCES roles(id), PRIMARY KEY(user_id,role_id));
CREATE TABLE refresh_tokens (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES users(id), token_hash text NOT NULL, expires_at timestamptz NOT NULL, revoked_at timestamptz);
CREATE TABLE mfa_secrets (user_id uuid PRIMARY KEY REFERENCES users(id), encrypted_secret bytea NOT NULL);
CREATE TABLE audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid, event_type varchar(100) NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), details jsonb NOT NULL DEFAULT '{}');
CREATE TABLE contact_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, email text NOT NULL, category varchar(50) NOT NULL, message text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE company_aliases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid REFERENCES companies(id), alias text NOT NULL);
CREATE TABLE products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, description text);
CREATE TABLE company_products (company_id uuid REFERENCES companies(id), product_id uuid REFERENCES products(id), PRIMARY KEY(company_id,product_id));
CREATE TABLE industries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code varchar(30) NOT NULL, scheme varchar(30) NOT NULL, name text NOT NULL);
CREATE TABLE ipos (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid REFERENCES companies(id), status varchar(50), listing_date date);
CREATE TABLE filings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid REFERENCES companies(id), source_id varchar(100) REFERENCES sources(id), source_url text, retrieved_at timestamptz NOT NULL, confidence varchar(40), filing_type varchar(50), filed_at date);
CREATE TABLE shareholders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid REFERENCES companies(id), name text NOT NULL, source_id varchar(100) REFERENCES sources(id), source_url text, retrieved_at timestamptz NOT NULL, confidence varchar(40));
CREATE TABLE holdings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), shareholder_id uuid REFERENCES shareholders(id), company_id uuid REFERENCES companies(id), reported_at date, percentage numeric(8,4));
CREATE TABLE relationships (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), from_company uuid REFERENCES companies(id), to_company uuid REFERENCES companies(id), kind varchar(30), confidence varchar(40), source_id varchar(100) REFERENCES sources(id), source_url text, retrieved_at timestamptz NOT NULL);
CREATE TABLE news_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid REFERENCES companies(id), title text NOT NULL, url text NOT NULL, published_at timestamptz, source_id varchar(100) REFERENCES sources(id), retrieved_at timestamptz NOT NULL, confidence varchar(40));
CREATE TABLE risk_flags (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid REFERENCES companies(id), label text NOT NULL, source_id varchar(100) REFERENCES sources(id), source_url text, retrieved_at timestamptz NOT NULL, confidence varchar(40));
CREATE TABLE watchlists (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), name text NOT NULL);
CREATE TABLE notes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), watchlist_id uuid NOT NULL REFERENCES watchlists(id), user_id uuid NOT NULL REFERENCES users(id), company_id uuid REFERENCES companies(id), body text NOT NULL);
